    def readstr():
        return sys.stdin.readline().strip()

    t = int(readstr())
    results = []

    for _ in range(t):
        n = int(readstr())
        s = readstr()

        # Count the number of 0s and 1s in the string
        count_0 = s.count('0')
        count_1 = s.count('1')

        # If the counts are not equal, it's impossible to partition
        if count_0 != count_1:
            results.append("-1")
            continue

        # Try to find a valid rotation
        found = False
        for i in range(2 * n):
            # Rotate the string by one position
            rotated = s[i:] + s[:i]
            # Check if we can partition the rotated string
            count_0_left = 0
            count_1_left = 0
            b = []
            p = []
            for j in range(2 * n):
                if count_0_left < count_0 // 2:
                    if rotated[j] == '0':
                        count_0_left += 1
                        p.append(j + 1)
                    else:
                        b.append(j + 1)
                elif count_1_left < count_1 // 2:
                    if rotated[j] == '1':
                        count_1_left += 1
                        p.append(j + 1)
                    else:
                        b.append(j + 1)
                else:
                    break

            if count_0_left == count_0 // 2 and count_1_left == count_1 // 2:
                found = True
                results.append(f"{len(b)} {' '.join(map(str, b))}")
                results.append(f"{' '.join(map(str, p))}")
                break

        if not found:
            results.append("-1")

    for result in results:
